}
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

// ---- values
const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'e', v: e })
const num = (v) => ({ k: 'n', v })

// ---- parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let pos = 0
  let ranges = 0
  let okRanges = 0
  const peek = () => toks[pos]
  const isOp = (v) => pos < toks.length && toks[pos].t === 'op' && toks[pos].v === v
  const bad = new Error('syntax')
  function cmp() {
    let l = add()
    while (pos < toks.length && toks[pos].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[pos++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[pos++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { pos++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[pos++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) throw bad
    pos++
    if (tk.t === 'num') return { t: 'num', v: tk.v }
    if (tk.t === 'op') {
      if (tk.v !== '(') throw bad
      const e = cmp()
      if (!isOp(')')) throw bad
      pos++
      return { t: 'paren', e }
    }
    const name = tk.v
    if (isOp('(')) {
      pos++
      const argv = []
      if (!isOp(')')) {
        for (;;) {
          const a = cmp()
          if (a.t === 'range') okRanges++
          argv.push(a)
          if (isOp(',')) { pos++; continue }
          break
        }
      }
      if (!isOp(')')) throw bad
      pos++
      return { t: 'call', name: name.toUpperCase(), args: argv }
    }
    if (isOp(':')) {
      pos++
      const t2 = peek()
      if (!t2 || t2.t !== 'word') throw bad
      pos++
      if (isOp('(')) throw bad
      ranges++
      return { t: 'range', a: parseAddr(name), b: parseAddr(t2.v) }
    }
    const up = name.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddr(name) }
  }
  try {
    const tree = cmp()
    if (pos < toks.length) return null
    return { tree, misplaced: ranges !== okRanges }
  } catch (e) {
    if (e === bad) return null
    throw e
  }
}

function rangeCells(a, b) {
  const out = []
  const c1 = Math.min(a.ci, b.ci), c2 = Math.max(a.ci, b.ci)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) {
    let name = ''
    let n = c
    while (n > 0) { const r = (n - 1) % 26; name = String.fromCharCode(65 + r) + name; n = Math.floor((n - 1) / 26) }
    for (let r = r1; r <= r2; r++) out.push(name + r)
  }
  return out
}

function collectDeps(node, set) {
  switch (node.t) {
    case 'ref': if (node.a) set.add(node.a.key); break
    case 'range': if (node.a && node.b) for (const k of rangeCells(node.a, node.b)) set.add(k); break
    case 'bin': collectDeps(node.l, set); collectDeps(node.r, set); break
    case 'un': case 'paren': collectDeps(node.e, set); break
    case 'call': for (const a of node.args) collectDeps(a, set); break
  }
}

// ---- evaluation
const NUMLIT = /^-?[0-9]+(\.[0-9]+)?$/
const parsed = new Map()
const memo = new Map()
const active = new Set()

function cellValue(key) {
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  try { v = evalContent(cell.content) } finally { active.delete(key) }
  memo.set(key, v)
  return v
}

function evalContent(c) {
  if (c[0] === '=') {
    const p = parseFormula(c.slice(1))
    if (!p || p.misplaced) return err('#ERR!')
    return ev(p.tree)
  }
  if (c === '') return num(0)
  if (NUMLIT.test(c)) return num(Number(c))
  if (ERRORS.includes(c)) return err(c)
  return { k: 's', v: c }
}

function toNum(x) {
  if (x.k === 'e') return x
  if (x.k === 'n') return x
  if (x.k === 'b') return num(x.v ? 1 : 0)
  return err('#VALUE!')
}
function finite(v) { return Number.isFinite(v) ? num(v) : err('#DIV/0!') }

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] < rank[b.k] ? -1 : 1
  if (a.k === 's') return cpCompare(a.v, b.v)
  if (a.k === 'b') return a.v === b.v ? 0 : a.v ? 1 : -1
  return a.v === b.v ? 0 : a.v < b.v ? -1 : 1
}

function ev(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'paren': return ev(n.e)
    case 'ref': return n.a ? cellValue(n.a.key) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const x = toNum(ev(n.e))
      if (x.k === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.k === 'e') return l
        if (r.k === 'e') return r
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      const a = toNum(l), b = toNum(r)
      if (a.k === 'e') return a
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
  return err('#ERR!')
}

const FUNCS = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
function call(n) {
  if (!FUNCS.includes(n.name)) return err('#NAME?')
  const argc = n.args.length
  if (n.name === 'IF') {
    if (argc !== 3) return err('#ERR!')
    if (n.args[0].t === 'range') return err('#ERR!')
    const c = ev(n.args[0])
    if (c.k === 'e') return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    const br = n.args[truth ? 1 : 2]
    if (br.t === 'range') return err('#ERR!')
    return ev(br)
  }
  if (n.name === 'ABS') {
    if (argc !== 1 || n.args[0].t === 'range') return err('#ERR!')
    const x = toNum(ev(n.args[0]))
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (argc < 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) {
    if (a.t === 'range') {
      if (!a.a || !a.b) { vals.push(err('#REF!')); continue }
      for (const k of rangeCells(a.a, a.b)) vals.push(cellValue(k))
    } else vals.push(ev(a))
  }
  for (const v of vals) if (v.k === 'e') return v
  if (n.name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const xs = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    xs.push(x.v)
  }
  switch (n.name) {
    case 'SUM': return finite(xs.reduce((a, b) => a + b, 0))
    case 'MIN': return num(xs.reduce((a, b) => Math.min(a, b)))
    case 'MAX': return num(xs.reduce((a, b) => Math.max(a, b)))
    case 'AVG': return finite(xs.reduce((a, b) => a + b, 0) / xs.length)
  }
}

// ---- output
const sorted = [...cells.values()].map((c) => c.addr).sort((a, b) => a.ci - b.ci || a.row - b.row)
const out = []
for (const a of sorted) {
  if (mode === 'values') {
    const v = cellValue(a.key)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${a.key}=${s}`)
  } else {
    const c = cells.get(a.key).content
    const set = new Set()
    if (c[0] === '=') {
      const p = parseFormula(c.slice(1))
      if (p) collectDeps(p.tree, set)
    }
    const list = [...set].map(parseAddr).sort((x, y) => x.ci - y.ci || x.row - y.row)
    out.push(`${a.key}:` + list.map((x) => ' ' + x.key).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
